  'STEP 3' => 'ნაბიჯი 3',
  'Validate data and complete import' => 'გადაამოწმეთ მონაცემები და დაასრულეთ იმპორტი',
  'Instructions' => 'ინსტრუქციები',
  '1. Download the format file and fill it with proper data.' => '1. ჩამოტვირთეთ ფორმატის ფაილი და შეავსეთ იგი შესაბამისი მონაცემებით.',
  '2. You can download the example file to understand how the data must be filled.' => '2. შეგიძლიათ ჩამოტვირთოთ მაგალითის ფაილი იმის გასაგებად, თუ როგორ უნდა შეივსოს მონაცემები.',
  '4. After uploading stores you need to edit them and set stores`s logo and cover.' => '4. მაღაზიების ატვირთვის შემდეგ თქვენ უნდა შეცვალოთ ისინი და დააყენოთ მაღაზიების ლოგო და საფარი.',
  '5. You can get module id and  zone id from their list, please input the right ids.' => '5. თქვენ შეგიძლიათ მიიღოთ მოდულის ID და ზონის ID მათი სიიდან, გთხოვთ შეიყვანოთ სწორი ID.',
  '6. For delivery time the format is "from-to type" for example: "30-40 min". Also you can use days or hours as type. Please be carefull about this format or leave this field empty.' => '6. მიწოდების დროისთვის ფორმატი არის ტიპიდან-მდე მაგალითად: 30-40 წთ. ასევე შეგიძლიათ გამოიყენოთ დღეები ან საათები ტიპად. გთხოვთ, იყავით ფრთხილად ამ ფორმატის მიმართ ან დატოვეთ ეს ველი ცარიელი.',
  '7. You can upload your store images in store folder from gallery, and copy image`s path.' => '7. შეგიძლიათ ატვირთოთ თქვენი მაღაზიის სურათები მაღაზიის საქაღალდეში გალერეიდან და დააკოპიროთ სურათის გზა.',
  '8. Default password for store is 12345678.' => '8. მაღაზიის ნაგულისხმევი პაროლი არის 12345678.',
  '9. Latitude must be a number between -90 to 90 and Longitude must a number between -180 to 180. Otherwise it will create server error' => '9. გრძედი უნდა იყოს რიცხვი -90-დან 90-მდე და Longitude უნდა იყოს რიცხვი -180-დან 180-მდე. წინააღმდეგ შემთხვევაში ის შექმნის სერვერის შეცდომას',
