  'Turn OFF' => 'გამორთეთ',
  'Enabling mail configuration services will allow the system to send emails. Please ensure that you have correctly configured the SMTP settings to avoid potential issues with email delivery.' => 'ფოსტის კონფიგურაციის სერვისების ჩართვა სისტემას ელფოსტის გაგზავნის საშუალებას მისცემს. გთხოვთ, დარწმუნდეთ, რომ სწორად დააკონფიგურირეთ SMTP პარამეტრები, რათა თავიდან აიცილოთ პოტენციური პრობლემები ელფოსტის მიწოდებასთან დაკავშირებით.',
  'Disabling mail configuration services will prevent the system from sending emails. Please only turn off this service if you intend to temporarily suspend email sending. Note that this may affect system functionality that relies on email communication.' => 'ფოსტის კონფიგურაციის სერვისების გამორთვა ხელს შეუშლის სისტემას წერილების გაგზავნაში. გთხოვთ, გამორთოთ ეს სერვისი მხოლოდ იმ შემთხვევაში, თუ თქვენ აპირებთ ელფოსტის გაგზავნის დროებით შეჩერებას. გაითვალისწინეთ, რომ ამან შეიძლება გავლენა მოახდინოს სისტემის ფუნქციონირებაზე, რომელიც ეყრდნობა ელექტრონული ფოსტის კომუნიკაციას.',
  '*By Turning OFF mail configuration, all your mailing services will be off.' => '*ფოსტის კონფიგურაციის გამორთვით თქვენი ყველა საფოსტო სერვისი გამორთული იქნება.',
