  'Go to test mail to check that its work perfectly or not!' => 'გადადით სატესტო ფოსტაზე, რათა შეამოწმოთ მუშაობს იდეალურად თუ არა!',
  'Send a Test Mail to Your Email ? ' => 'გამოგიგზავნოთ სატესტო წერილი თქვენს ელფოსტაზე?',
  'A test mail will be send to your email to confirm it works perfectly.' => 'სატესტო წერილი გაიგზავნება თქვენს ელფოსტაზე, რათა დაადასტუროთ, რომ ის იდეალურად მუშაობს.',
  'Find SMTP Server Details' => 'იპოვეთ SMTP სერვერის დეტალები',
  'Contact your email service provider or IT administrator to obtain the SMTP server details, such as hostname, port, username, and password.' => 'დაუკავშირდით თქვენი ელ.ფოსტის სერვისის პროვაიდერს ან IT ადმინისტრატორს SMTP სერვერის დეტალების მისაღებად, როგორიცაა ჰოსტის სახელის პორტის მომხმარებლის სახელი და პაროლი.',
  'Note: If you\'re not sure where to find these details, check the email provider\'s documentation or support resources for guidance.' => 'შენიშვნა: თუ არ ხართ დარწმუნებული, სად იპოვოთ ეს დეტალები, შეამოწმეთ ელ.ფოსტის პროვაიდერის დოკუმენტაცია ან მხარდაჭერის რესურსები ხელმძღვანელობისთვის.',
  'Configure SMTP Settings' => 'SMTP პარამეტრების კონფიგურაცია',
  'Go to the SMTP mail setup page in the admin panel.' => 'გადადით SMTP ფოსტის დაყენების გვერდზე ადმინისტრაციულ პანელში.',
  'Enter the obtained SMTP server details, including the hostname, port, username, and password.' => 'შეიყვანეთ მიღებული SMTP სერვერის დეტალები, მათ შორის ჰოსტის სახელის პორტის მომხმარებლის სახელი და პაროლი.',
  'Choose the appropriate encryption method (e.g., SSL, TLS) if required. Save the settings.' => 'საჭიროების შემთხვევაში აირჩიეთ შესაბამისი დაშიფვრის მეთოდი (მაგ. SSL TLS). შეინახეთ პარამეტრები.',
  'Test SMTP Connection' => 'შეამოწმეთ SMTP კავშირი',
  'Click on the "Send Test Mail" button to verify the SMTP connection.' => 'დააწკაპუნეთ სატესტო ფოსტის გაგზავნის ღილაკზე SMTP კავშირის დასადასტურებლად.',
  'If successful, you will see a confirmation message indicating that the connection is working fine.' => 'წარმატების შემთხვევაში ნახავთ დადასტურების შეტყობინებას, რომელიც მიუთითებს, რომ კავშირი კარგად მუშაობს.',
  'If not, double-check your SMTP settings and try again.' => 'თუ არა, ორჯერ შეამოწმეთ თქვენი SMTP პარამეტრები და სცადეთ ხელახლა.',
