  '* This discount is applied on all the items in your store' => '* ეს ფასდაკლება ვრცელდება თქვენს მაღაზიაში არსებულ ყველა პროდუქტზე',
  '* When this discount is available  is applied on all the items in this stores.' => '* როდესაც ეს ფასდაკლება ხელმისაწვდომია, ვრცელდება ამ მაღაზიის ყველა პროდუქტზე.',
  '*By Turning OFF mail configuration  all your mailing services will be off.' => '*ფოსტის კონფიგურაციის გამორთვით თქვენი ყველა საფოსტო სერვისი გამორთული იქნება.',
  '*By Turning ON Refund Mode  Customers Can Sent Refund Requests' => '*თანხის დაბრუნების რეჟიმის ჩართვით მომხმარებელს შეუძლია თანხის დაბრუნების მოთხოვნების გაგზავნა',
  '*Customers_cannot_request_a_Refund_if_the_Admin_does_not_specify_a_cause_for_cancellation _even_though_they_see_the_Cancel_Order_option._So_Admin_MUST_provide_a_proper_Refund_Reason_and_select_the_related_user.' => '*მომხმარებლები ვერ მოითხოვენ თანხის დაბრუნებას, თუ ადმინისტრატორი არ მიუთითებს გაუქმების მიზეზს, მიუხედავად იმისა, რომ ისინი ხედავენ შეკვეთის გაუქმების ვარიანტს. ასე რომ, ადმინისტრატორმა უნდა მიუთითოს თანხის დაბრუნების სათანადო მიზეზი და შეარჩიოს დაკავშირებული მომხმარებელი.',
  '*If_the_Admin_enables_the_âRefund_Request_Modeâ _customers_can_request_a_refund.' => '*თუ ადმინისტრატორი ჩართავს „თანხის დაბრუნების მოთხოვნის რეჟიმს“ მომხმარებელს შეუძლია მოითხოვოს თანხის დაბრუნება.',
  '*If_the_Admin_enables_the_âRefund_Request_Modeâ _customers_can_request_a_refund.' => '*თუ ადმინისტრატორი ჩართავს âანაზღაურების მოთხოვნის რეჟიმს მომხმარებელს შეუძლია მოითხოვოს თანხის დაბრუნება.',
  '*If_the_Admin_enables_the_‘Refund_Request_Mode’ _customers_can_request_a_refund.' => '*თუ ადმინისტრატორი ჩართავს „თანხის დაბრუნების მოთხოვნის რეჟიმს“, მომხმარებელს შეუძლია მოითხოვოს თანხის დაბრუნება.',
