  'This report will show all the orders in which the store discount has been used. The store discounts are: Free delivery, Coupon discount & item discounts(partial according to order commission).' => 'ეს ანგარიში აჩვენებს ყველა შეკვეთას, რომლებშიც გამოყენებულია მაღაზიის ფასდაკლება. მაღაზიის ფასდაკლებებია: უფასო მიტანის კუპონის ფასდაკლება და პროდუქციის ფასდაკლება (ნაწილობრივი შეკვეთის საკომისიოს მიხედვით).',
