  'If you disable this, the Deliveryman will deliver the order and update the status. He doesn’t need to verify the order with any code.' => 'თუ ამას გამორთავთ, მიმწოდებელი გადასცემს შეკვეთას და განაახლებს სტატუსს. მას არ სჭირდება შეკვეთის გადამოწმება რაიმე კოდით.',
  'If you enable this, customers can place an order by simply uploading their prescriptions in the Pharmacy module from the Customer App or Website. Stores can enable/disable this feature from store settings if needed.' => 'თუ ამას ჩართავთ, კლიენტებს შეუძლიათ შეკვეთის განთავსება უბრალოდ ატვირთონ თავიანთი რეცეპტები აფთიაქის მოდულში მომხმარებელთა აპიდან ან ვებსაიტიდან. საჭიროების შემთხვევაში მაღაზიებს შეუძლიათ ჩართონ/გამორთონ ეს ფუნქცია მაღაზიის პარამეტრებიდან.',
  'If disabled, this feature will be hidden from the Customer App, Website, and Store App & Panel.' => 'თუ გამორთულია, ეს ფუნქცია დაიმალება მომხმარებელთა აპლიკაციის ვებსაიტიდან და მაღაზიის აპისა და პანელიდან.',
  'If you enable this, customers can use the Home Delivery Option during checkout from the Customer App or Website.' => 'თუ ამას ჩართავთ, კლიენტებს შეუძლიათ გამოიყენონ სახლში მიტანის ვარიანტი კლიენტის აპიდან ან ვებსაიტიდან შეკვეთის დროს.',
