  '*Users_cannot_cancel_an_order_if_the_Admin_does_not_specify_a_cause_for_cancellation _even_though_they_see_the_‘Cancel_Order‘_option._So_Admin_MUST_provide_a_proper_Order_Cancellation_Reason_and_select_the_related_user.' => '*მომხმარებლები ვერ გააუქმებენ შეკვეთას, თუ ადმინისტრატორი არ მიუთითებს გაუქმების მიზეზს, მიუხედავად იმისა, რომ ისინი ხედავენ „შეკვეთის გაუქმებას“. ასე რომ, ადმინისტრატორმა უნდა მიუთითოს შეკვეთის გაუქმების სათანადო მიზეზი და შეარჩიოს დაკავშირებული მომხმარებელი.',
