  'panel_login_page_Url' => 'პანელის შესვლის გვერდი Url',
  'By enabling manual login, customers will get the option to create an account and log in using the necessary credentials & password in the app & website' => 'ხელით შესვლის ჩართვით, კლიენტები მიიღებენ შესაძლებლობას შექმნან ანგარიში და შევიდნენ აპსა და ვებსაიტში საჭირო სერთიფიკატებისა და პაროლის გამოყენებით',
  'With OTP Login, customers can log in using their phone number. while new customers can create accounts instantly.' => 'OTP Login-ით მომხმარებლებს შეუძლიათ შევიდნენ თავიანთი ტელეფონის ნომრის გამოყენებით. ხოლო ახალ მომხმარებლებს შეუძლიათ მყისიერად შექმნან ანგარიშები.',
  'With Social Login, customers can log in using social media credentials. while new customers can create accounts instantly.' => 'სოციალური შესვლის საშუალებით მომხმარებლებს შეუძლიათ შევიდნენ სოციალური მედიის სერთიფიკატების გამოყენებით. ხოლო ახალ მომხმარებლებს შეუძლიათ მყისიერად შექმნან ანგარიშები.',
  'Enabling Google Login, customers can log in to the site using their existing Gmail credentials.' => 'Google Login-ის ჩართვით კლიენტებს შეუძლიათ შევიდნენ საიტზე არსებული Gmail-ის სერთიფიკატების გამოყენებით.',
  'Enabling Facebook Login, customers can log in to the site using their existing Facebook credentials' => 'ფეისბუქის შესვლის ჩართვით, მომხმარებლებს შეუძლიათ შევიდნენ საიტზე არსებული Facebook რწმუნებათა სიგელების გამოყენებით',
  'Enabling Apple Login, customers can log in to the site using their existing Apple login credentials, Only for Apple devices' => 'Apple Login-ის ჩართვით, მომხმარებლებს შეუძლიათ შევიდნენ საიტზე არსებული Apple შესვლის სერთიფიკატების გამოყენებით, მხოლოდ Apple მოწყობილობებისთვის',
  'Verification' => 'გადამოწმება',
  'The option you select from below will need to verify by customer from customer app/website.' => 'ქვემოდან არჩეული ვარიანტი დამკვეთის მიერ დამკვეთის აპიდან/ვებგვერდიდან უნდა გადაამოწმოს.',
  'If Email verification is on, Customers must verify their email address with an OTP to complete the signup process.' => 'თუ ელფოსტის დადასტურება ჩართულია, მომხმარებლებმა უნდა დაადასტურონ თავიანთი ელფოსტის მისამართი OTP-ით, რათა დაასრულონ რეგისტრაციის პროცესი.',
  'If Phone Number verification is on, Customers must verify their Phone Number with an OTP to complete the signup process.' => 'თუ ტელეფონის ნომრის დადასტურება ჩართულია, მომხმარებლებმა უნდა დაადასტურონ თავიანთი ტელეფონის ნომერი OTP-ით რეგისტრაციის პროცესის დასასრულებლად.',
  'Important Alert !' => 'მნიშვნელოვანი გაფრთხილება!',
  'At least one login method must remain active for the customer; otherwise, they will be unable to log in to the system' => 'მომხმარებლისთვის მინიმუმ ერთი შესვლის მეთოდი უნდა დარჩეს აქტიური, წინააღმდეგ შემთხვევაში, ისინი ვერ შეძლებენ სისტემაში შესვლას',
  'Set Up SMS Configuration First' => 'ჯერ დააყენეთ SMS კონფიგურაცია',
  'It looks like your SMS configuration is not set up yet. To enable the OTP system, please set up the SMS configuration first.' => 'როგორც ჩანს, თქვენი SMS კონფიგურაცია ჯერ არ არის დაყენებული. OTP სისტემის ჩასართავად, გთხოვთ, ჯერ დააყენოთ SMS კონფიგურაცია.',
  'Go to SMS Configuration' => 'გადადით SMS კონფიგურაციაზე',
  'If you are activating only social login as the login method, you must enable at least one option between Google and Facebook for Android users.' => 'თუ თქვენ ააქტიურებთ მხოლოდ სოციალურ შესვლას, როგორც შესვლის მეთოდს, უნდა ჩართოთ მინიმუმ ერთი ვარიანტი Google-სა და Facebook-ს შორის Android-ის მომხმარებლებისთვის.',
  'If you are activating social login as the login method, you must enable at least one option between Google, Facebook & Apple.' => 'თუ თქვენ ააქტიურებთ სოციალურ შესვლას, როგორც შესვლის მეთოდს, უნდა ჩართოთ მინიმუმ ერთი ვარიანტი Google-ს, Facebook-სა და Apple-ს შორის.',
  'Set Up Google Configuration First' => 'ჯერ დააყენეთ Google-ის კონფიგურაცია',
  'It looks like your Google Login configuration is not set up yet. To enable the Google Login option, please set up the Google configuration first.' => 'როგორც ჩანს, თქვენი Google Login-ის კონფიგურაცია ჯერ არ არის დაყენებული. Google შესვლის ოფციის ჩასართავად, გთხოვთ, ჯერ დააყენოთ Google-ის კონფიგურაცია.',
  'Go to Google Configuration' => 'გადადით Google Configuration-ზე',
  'Set Up Facebook Configuration First' => 'ჯერ დააყენეთ Facebook-ის კონფიგურაცია',
  'It looks like your Facebook Login configuration is not set up yet. To enable the Facebook Login option, please set up the Facebook configuration first.' => 'როგორც ჩანს, თქვენი Facebook შესვლის კონფიგურაცია ჯერ არ არის დაყენებული. Facebook შესვლის ოფციის ჩასართავად, გთხოვთ, ჯერ დააყენოთ Facebook-ის კონფიგურაცია.',
  'Go to Facebook Configuration' => 'გადადით Facebook Configuration-ზე',
  'Set Up Apple Configuration First' => 'ჯერ დააყენეთ Apple-ის კონფიგურაცია',
  'It looks like your Apple Login configuration is not set up yet. To enable the Apple Login option, please set up the Apple configuration first.' => 'როგორც ჩანს, თქვენი Apple შესვლის კონფიგურაცია ჯერ არ არის დაყენებული. Apple შესვლის ოფციის ჩასართავად, გთხოვთ, ჯერ დააყენოთ Apple-ის კონფიგურაცია.',
  'Go to Apple Configuration' => 'გადადით Apple-ის კონფიგურაციაზე',
  'It looks like your SMS configuration is not set up yet. To enable the phone verification, please set up the SMS configuration first.' => 'როგორც ჩანს, თქვენი SMS კონფიგურაცია ჯერ არ არის დაყენებული. ტელეფონის დადასტურების ჩასართავად, გთხოვთ, ჯერ დააყენოთ SMS კონფიგურაცია.',
  'Set Up Email Configuration First' => 'ჯერ დააყენეთ ელ.ფოსტის კონფიგურაცია',
  'It looks like your Email configuration is not set up yet. To enable the email verification, please set up the SMS configuration first.' => 'როგორც ჩანს, თქვენი ელფოსტის კონფიგურაცია ჯერ არ არის დაყენებული. ელ.ფოსტის დადასტურების ჩასართავად, გთხოვთ, ჯერ დააყენოთ SMS კონფიგურაცია.',
  'Go to Mail Configuration' => 'გადადით ფოსტის კონფიგურაციაზე',
  'login_settings_data_updated_successfully' => 'შესვლის პარამეტრების მონაცემები წარმატებით განახლდა',
