  'If you disable Firebase OTP, users will no longer receive verification codes via Firebase. You must activate Email or SMS verification as an alternative' => 'თუ თქვენ გამორთავთ Firebase OTP, მომხმარებლები აღარ მიიღებენ დამადასტურებელ კოდებს Firebase-ის მეშვეობით. ალტერნატიულად უნდა გაააქტიუროთ ელ.ფოსტის ან SMS დადასტურება',
