  'Let’s Setup' => 'მოდით დავაყენოთ',
  'Common types include' => 'გავრცელებული ტიპები მოიცავს',
  'VAT (Value Added Tax)' => 'დღგ (დამატებული ღირებულების გადასახადი)',
  'GST (Goods & Services Tax)' => 'GST (საქონელი და სერვისების გადასახადი)',
  'Service Tax' => 'მომსახურების გადასახადი',
  'Sales Tax' => 'გაყიდვების გადასახადი',
  'Why Set Up Taxes ?' => 'რატომ დააწესეთ გადასახადები?',
  'Enabling tax in your system helps you:' => 'თქვენს სისტემაში გადასახადის ჩართვა დაგეხმარებათ:',
  'Stay legally compliant with local tax laws' => 'დაიცავით კანონიერად ადგილობრივი საგადასახადო კანონები',
  'Automatically calculate and apply the correct tax during checkout' => 'ავტომატურად გამოთვალეთ და გამოიყენეთ სწორი გადასახადი შეკვეთის დროს',
  'Show clear and accurate pricing to customers' => 'აჩვენეთ მკაფიო და ზუსტი ფასები კლიენტებს',
  'Generate ready-to-use VAT/GST reports' => 'შექმენით მზა დღგ/GST ანგარიშები',
  'Once you set up your tax correctly, the system will automatically handle calculations for every order.' => 'გადასახადის სწორად დაყენების შემდეგ, სისტემა ავტომატურად ამუშავებს გამოთვლებს ყოველი შეკვეთისთვის.',
  'Activate the Tax Status' => 'გააქტიურეთ საგადასახადო სტატუსი',
  'Turn ON the Status toggle to make the tax active.' => 'გადასახადის გასააქტიურებლად ჩართეთ სტატუსის გადამრთველი.',
  'If it’s OFF, the tax will be saved but not applied to any transaction.' => 'თუ ის გამორთულია, გადასახადი შეინახება, მაგრამ არ ვრცელდება არცერთ ტრანზაქციაზე.',
  'Enter a Tax Name' => 'შეიყვანეთ საგადასახადო სახელი',
  'Go to the Tax Name field and enter your preferred name.' => 'გადადით Tax Name ველში და შეიყვანეთ სასურველი სახელი.',
  'Example: Service Tax, VAT, GST, Sales Tax, etc.' => 'მაგალითი: მომსახურების გადასახადი, დღგ, GST, გაყიდვების გადასახადი და ა.შ.',
  'Set the Tax Rate' => 'დააყენეთ საგადასახადო განაკვეთი',
  'In the Tax Rate box, enter the percentage (e.g., 10%).' => 'საგადასახადო განაკვეთის ველში შეიყვანეთ პროცენტი (მაგ., 10%).',
  'This is the rate that will be applied to all taxable items or services.' => 'ეს არის განაკვეთი, რომელიც გამოყენებული იქნება ყველა დასაბეგრი ნივთსა თუ მომსახურებაზე.',
  'Save the Tax' => 'დაზოგე გადასახადი',
  'Click Submit to add the new tax.' => 'ახალი გადასახადის დასამატებლად დააჭირეთ გაგზავნას.',
  'Click Reset if you need to clear the form before saving.' => 'დააწკაპუნეთ გადატვირთვაზე, თუ შენახვამდე ფორმის გასუფთავება გჭირდებათ.',
  'You can create multiple taxes for different purposes — for example, separate ones for product, service, and delivery.' => 'თქვენ შეგიძლიათ შექმნათ მრავალი გადასახადი სხვადასხვა მიზნებისთვის - მაგალითად, ცალკეული გადასახადები პროდუქტის, მომსახურებისა და მიწოდებისთვის.',
  'Follow these steps to add a new tax rate:' => 'მიჰყევით ამ ნაბიჯებს ახალი საგადასახადო განაკვეთის დასამატებლად:',
  'Edit or Manage Existing Taxes' => 'არსებული გადასახადების რედაქტირება ან მართვა',
  'Once a tax is created, you cannot change its name or delete it (for data integrity).' => 'გადასახადის შექმნის შემდეგ, თქვენ არ შეგიძლიათ შეცვალოთ მისი სახელი ან წაშალოთ იგი (მონაცემთა მთლიანობისთვის).',
  'However, you can update the tax rate anytime if your government updates the tax percentage.' => 'თუმცა, თქვენ შეგიძლიათ განაახლოთ გადასახადის განაკვეთი ნებისმიერ დროს, თუ თქვენი მთავრობა განაახლებს გადასახადის პროცენტს.',
  'Manage all your created taxes easily from the Tax List page.' => 'მართეთ ყველა თქვენი შექმნილი გადასახადი მარტივად საგადასახადო სიის გვერდიდან.',
  'Use the Export button to download a copy for backup or accounting records.' => 'გამოიყენეთ ექსპორტის ღილაკი სარეზერვო ან სააღრიცხვო ჩანაწერებისთვის ასლის ჩამოსატვირთად.',
  'Toggle the Status on or off to quickly enable or disable a tax.' => 'ჩართეთ ან გამორთეთ სტატუსი, რათა სწრაფად ჩართოთ ან გამორთოთ გადასახადი.',
  'You can decide:' => 'თქვენ შეგიძლიათ გადაწყვიტოთ:',
  'Whether tax should be included in the product price or added separately' => 'უნდა ჩაითვალოს თუ არა გადასახადი პროდუქტის ფასში თუ ცალკე დაემატოს',
  'Which parts of the order should have taxes applied — items, delivery fees, or packaging' => 'შეკვეთის რომელ ნაწილებზე უნდა იყოს გამოყენებული გადასახადები - ნივთები, მიწოდების საფასური ან შეფუთვა',
  'This gives you full control over how your business handles tax visibility and accuracy.' => 'ეს გაძლევთ სრულ კონტროლს იმაზე, თუ როგორ ამუშავებს თქვენი ბიზნესი საგადასახადო ხილვადობასა და სიზუსტეს.',
  'Tax Calculation Method' => 'გადასახადის გაანგარიშების მეთოდი',
  'You can choose one of two ways to calculate tax:' => 'გადასახადის გამოსათვლელად შეგიძლიათ აირჩიოთ ერთი ორი გზა:',
  'Calculate Tax Included in Product Price' => 'გამოთვალეთ გადასახადი, რომელიც შედის პროდუქტის ფასში',
  'The tax is already included in the listed item price.' => 'გადასახადი უკვე შედის ნივთის ჩამოთვლილ ფასში.',
  'The customer sees a single total price (no separate tax line).' => 'მომხმარებელი ხედავს ერთ მთლიან ფასს (ცალკე საგადასახადო ხაზი არ არის).',
  'Invoices and reports won’t show separate VAT amounts.' => 'ინვოისები და ანგარიშები არ აჩვენებს დღგ-ს ცალკეულ თანხებს.',
  'Use this method if your displayed prices are “tax-included.' => 'გამოიყენეთ ეს მეთოდი, თუ თქვენს მიერ ნაჩვენები ფასები "მოიცავს გადასახადს.',
  'Calculate Tax Excluded from Product Price' => 'გამოთვალეთ გადასახადი, რომელიც გამორიცხულია პროდუქტის ფასიდან',
  'The tax is added on top of the item price.' => 'გადასახადი ემატება ნივთის ფასს.',
  'Customers will see a separate tax line during checkout and in their invoice.' => 'კლიენტები იხილავენ ცალკე საგადასახადო ხაზს გადახდისას და მათ ინვოისში.',
  'This method gives you clear, transparent VAT reporting.' => 'ეს მეთოდი გაძლევთ მკაფიო, გამჭვირვალე დღგ-ს ანგარიშგებას.',
  'Recommendation: Use “Tax Excluded from Product Price” if you want to show taxes separately for better reporting.' => 'რეკომენდაცია: გამოიყენეთ „გადასახადი, რომელიც გამორიცხულია პროდუქტის ფასიდან“, თუ გსურთ ცალ-ცალკე აჩვენოთ გადასახადები უკეთესი ანგარიშისთვის.',
  'Tax Effect on Orders' => 'საგადასახადო ეფექტი შეკვეთებზე',
  'Before activation:' => 'გააქტიურებამდე:',
  'Orders placed earlier will not have any tax added.' => 'ადრე განთავსებულ შეკვეთებს არ დაემატება გადასახადი.',
  'After activation:' => 'გააქტიურების შემდეგ:',
  'All new orders will automatically calculate and apply the correct tax.' => 'ყველა ახალი შეკვეთა ავტომატურად გამოითვლება და გამოიყენებს სწორ გადასახადს.',
  'After deactivation:' => 'დეაქტივაციის შემდეგ:',
  'If you turn off tax again, future orders will not include tax until reactivated.' => 'თუ კვლავ გამორთავთ გადასახადს, მომავალი შეკვეთები არ მოიცავს გადასახადს ხელახლა გააქტიურებამდე.',
  'This ensures older orders stay accurate while new ones follow updated rules.' => 'ეს უზრუნველყოფს ძველი შეკვეთების სიზუსტეს, ხოლო ახლები განახლებულ წესებს იცავენ.',
  'Flexible Tax Application Options' => 'მოქნილი საგადასახადო განაცხადის პარამეტრები',
  'Order-wise Tax:' => 'შეკვეთის მიხედვით გადასახადი:',
  'One flat tax rate applies to the total order.' => 'მთლიან შეკვეთაზე მოქმედებს ერთი უცვლელი გადასახადის განაკვეთი.',
  'Product-wise Tax: ' => 'პროდუქტის გადასახადი: ',
  'Each product or food item can have its own tax rate.' => 'თითოეულ პროდუქტს ან საკვებ პროდუქტს შეიძლება ჰქონდეს საკუთარი გადასახადის განაკვეთი.',
  'Category-wise Tax: ' => 'კატეგორიის მიხედვით გადასახადი: ',
  'Different product categories can carry different tax rates.' => 'სხვადასხვა კატეგორიის პროდუქციას შეიძლება ჰქონდეს განსხვავებული გადასახადის განაკვეთები.',
  'This flexibility lets you match complex tax rules for restaurants, grocery stores, or other service types.' => 'ეს მოქნილობა საშუალებას გაძლევთ დააკმაყოფილოთ რთული საგადასახადო წესები რესტორნებისთვის, სასურსათო მაღაზიებისთვის ან სხვა ტიპის სერვისებისთვის.',
  'Uploaded Prescription Orders (Pharmacy Module Only)' => 'ატვირთული რეცეპტის შეკვეთები (მხოლოდ სააფთიაქო მოდული)',
  'For pharmacy modules, tax applies order-wise on uploaded prescription orders.' => 'სააფთიაქო მოდულებისთვის, გადასახადი ვრცელდება შეკვეთის მიხედვით ატვირთულ რეცეპტებზე.',
  'You can set the tax type and rate specifically for these orders.' => 'თქვენ შეგიძლიათ დააყენოთ გადასახადის ტიპი და განაკვეთი სპეციალურად ამ შეკვეთებისთვის.',
  'You can also configure tax for packaging charges.' => 'თქვენ ასევე შეგიძლიათ დააკონფიგურიროთ გადასახადი შეფუთვის გადასახადისთვის.',
  'If enabled, packaging costs will include tax as per your setup — ensuring your total billing remains compliant.' => 'თუ ჩართულია, შეფუთვის ხარჯები მოიცავს გადასახადს თქვენი დაყენების მიხედვით - იმის უზრუნველსაყოფად, რომ თქვენი მთლიანი ბილინგი დარჩება შესაბამისობაში.',
  'Example: If packaging costs $2 and tax is 10%, the total will show as $2.20.' => 'მაგალითი: თუ შეფუთვა ღირს $2 და გადასახადი არის 10%, ჯამი გამოჩნდება $2.20.',
  'Final Step – Save Your Setup' => 'საბოლოო ნაბიჯი - შეინახეთ დაყენება',
  'After completing all configurations:' => 'ყველა კონფიგურაციის დასრულების შემდეგ:',
  'Click Save Information to apply changes.' => 'ცვლილებების გამოსაყენებლად დააჭირეთ ინფორმაციის შენახვას.',
  'Click Reset if you want to start over or discard unsaved edits.' => 'დააწკაპუნეთ გადატვირთვაზე, თუ გსურთ თავიდან დაიწყოთ ან გააუქმოთ შენახული რედაქტირებები.',
  'Once saved, your tax setup will instantly affect all applicable orders moving forward.' => 'შენახვის შემდეგ, თქვენი საგადასახადო დაყენება მყისიერად იმოქმედებს ყველა მოქმედ შეკვეთაზე, რომელიც წინ მიიწევს.',
