  'This feature allows the admin to configure how and when earnings are disbursed to restaurants and delivery personnel. Proper setup ensures timely payouts, automated processing, and compliance with operational rules.' => 'ეს ფუნქცია ადმინისტრატორს საშუალებას აძლევს დააკონფიგურიროს, როგორ და როდის გაიცემა შემოსავალი რესტორნებში და მიწოდების პერსონალზე. სათანადო დაყენება უზრუნველყოფს დროულ გადახდას, ავტომატიზირებულ დამუშავებას და ოპერაციულ წესებთან შესაბამისობას.',
  'Disbursement Request Setup' => 'გაცემის მოთხოვნის დაყენება',
  'The System PHP Path specifies the location of the PHP executable file that will be used to run automated disbursement scripts. Setting the correct PHP path ensures that the system can execute scheduled or automated disbursement processes without errors.' => 'System PHP Path განსაზღვრავს PHP შესრულებადი ფაილის ადგილმდებარეობას, რომელიც გამოყენებული იქნება ავტომატური გაცემის სკრიპტების გასაშვებად. სწორი PHP ბილიკის დაყენება უზრუნველყოფს, რომ სისტემას შეუძლია შეცდომის გარეშე შეასრულოს დაგეგმილი ან ავტომატიზირებული გაცემის პროცესები.',
  'The system automatically processes payouts according to predefined schedules (daily, weekly, or monthly).' => 'სისტემა ავტომატურად ამუშავებს გადახდებს წინასწარ განსაზღვრული გრაფიკის მიხედვით (ყოველდღიური, ყოველკვირეული ან ყოველთვიური).',
  'Automated Disbursement' => 'ავტომატური გაცემა',
  'Cron Command for Disbursement' => 'Cron Command for disbursement',
  'Admin reviews and approves each payout request before processing.' => 'ადმინისტრატორი განიხილავს და ამტკიცებს გადახდის თითოეულ მოთხოვნას დამუშავებამდე.',
  'Manual Disbursement' => 'ხელით გაცემა',
  'The system supports two types of disbursement requests for restaurants and delivery personnel: Manual and Automated. These settings determine how earnings are transferred from the platform to the recipients.' => 'სისტემა მხარს უჭერს რესტორნებსა და ადგილზე მიტანის პერსონალის გაცემის მოთხოვნის ორ ტიპს: მექანიკურ და ავტომატურს. ეს პარამეტრები განსაზღვრავს, თუ როგორ გადაეცემა შემოსავალი პლატფორმიდან მიმღებებზე.',
  'The Disbursement Setup feature allows the admin to manage the payout of earnings to restaurants and delivery personnel. It ensures timely and accurate settlements based on completed orders, commissions, and deductions.' => 'გაცემის დაყენების ფუნქცია ადმინისტრატორს საშუალებას აძლევს მართოს შემოსავლების გადახდა რესტორნებში და მიწოდების პერსონალისთვის. ის უზრუნველყოფს დროულ და ზუსტ ანგარიშსწორებას დასრულებული შეკვეთების, საკომისიოს და გამოქვითვის საფუძველზე.',
  'Disbursement Guideline' => 'გაცემის სახელმძღვანელო',
  'This feature allows the admin to configure how and when earnings are disbursed to vendors and delivery personnel. Proper setup ensures timely payouts, automated processing, and compliance with operational rules.' => 'ეს ფუნქცია ადმინისტრატორს საშუალებას აძლევს დააკონფიგურიროს, როგორ და როდის გაიცემა შემოსავალი მოვაჭრეებისთვის და მიწოდების პერსონალისთვის. სათანადო დაყენება უზრუნველყოფს დროულ გადახდას, ავტომატიზირებულ დამუშავებას და ოპერაციულ წესებთან შესაბამისობას.',
  'The system supports two types of disbursement requests for vendors and delivery personnel: Manual and Automated. These settings determine how earnings are transferred from the platform to the recipients.' => 'სისტემა მხარს უჭერს ორი სახის გაცემის მოთხოვნას მოვაჭრეებისთვის და მიწოდების პერსონალისთვის: მექანიკური და ავტომატური. ეს პარამეტრები განსაზღვრავს, თუ როგორ გადაეცემა შემოსავალი პლატფორმიდან მიმღებებზე.',
  'The Disbursement Setup feature allows the admin to manage the payout of earnings to vendors and delivery personnel. It ensures timely and accurate settlements based on completed orders, commissions, and deductions.' => 'გაცემის დაყენების ფუნქცია ადმინისტრატორს საშუალებას აძლევს მართოს შემოსავლების გადახდა გამყიდველებისთვის და მიწოდების პერსონალისთვის. ის უზრუნველყოფს დროულ და ზუსტ ანგარიშსწორებას დასრულებული შეკვეთების, საკომისიოს და გამოქვითვის საფუძველზე.',
