  'default_zone' => 'ნაგულისხმევი ზონა',
  'Default_Status' => 'ნაგულისხმევი სტატუსი',
  'If_you_set_this_zone as default for customers who visit the app or website without choosing a location.' => 'თუ დააყენებთ ამ ზონას ნაგულისხმევად იმ მომხმარებლებისთვის, რომლებიც სტუმრობენ აპს ან ვებსაიტს მდებარეობის არჩევის გარეშე.',
  'Want_to_make_this_as_default_zone?' => 'გსურთ გახადოთ ეს ნაგულისხმევ ზონად?',
