  'At least one delivery method Home Delivery or Takeaway must be selected for your business' => 'თქვენი ბიზნესისთვის უნდა იყოს არჩეული მიტანის მინიმუმ ერთი მეთოდი სახლში მიტანის ან მიტანის გარეშე',
  'Note : Don’t forget to save the information before leaving this page ' => 'შენიშვნა: არ დაგავიწყდეთ ინფორმაციის შენახვა ამ გვერდიდან გასვლამდე ',
  'To receive order notifications properly, select the notification type based on your preference:' => 'შეკვეთის შეტყობინებების სწორად მისაღებად, აირჩიეთ შეტყობინებების ტიპი თქვენი უპირატესობის მიხედვით:',
  'Manual Notification: You need to send order notifications manually for each order update.' => 'მექანიკური შეტყობინება: თქვენ უნდა გაგზავნოთ შეკვეთის შეტყობინებები ხელით თითოეული შეკვეთის განახლებისთვის.',
  'Firebase Notification: Order notifications will be sent automatically. Ensure' => 'Firebase შეტყობინება: შეკვეთის შეტყობინებები ავტომატურად გაიგზავნება. უზრუნველყოს',
  'is completed and notification messages are set up in the Notification Message section.' => 'დასრულებულია და შეტყობინებების შეტყობინებები დაყენებულია შეტყობინებების შეტყობინებების განყოფილებაში.',
  'Free Delivery Setup' => 'უფასო მიტანის დაყენება',
  'Are you sure to enable Free Delivery?' => 'დარწმუნებული ხართ, რომ ჩართავთ უფასო მიწოდებას?',
  'Are you sure to disable Free Delivery?' => 'დარწმუნებული ხართ, რომ გამორთავთ უფასო მიწოდებას?',
  'After enable customers will not be charged a delivery fee for eligible orders.' => 'ჩართვის შემდეგ მომხმარებელს არ დაერიცხება მიტანის საფასური შესაბამისი შეკვეთებისთვის.',
  'After disable delivery charges will apply to all new orders based on your delivery settings.' => 'გამორთვის შემდეგ, მიწოდების საფასური დაგეკისრებათ ყველა ახალ შეკვეთაზე თქვენი მიწოდების პარამეტრების მიხედვით.',
  'Vendors will no longer have the option to cancel. They will need to contact the admin to request any order cancellations.' => 'გამყიდველებს აღარ ექნებათ გაუქმების შესაძლებლობა. მათ უნდა დაუკავშირდნენ ადმინისტრატორს, რათა მოითხოვონ შეკვეთის გაუქმება.',
  'Vendors will be able to cancel orders directly from their panel if they cannot fulfill them.' => 'გამყიდველებს შეეძლებათ გააუქმონ შეკვეთები პირდაპირ მათი პანელიდან, თუ მათ არ შეუძლიათ შეასრულონ ისინი.',
  'Are you sure to not allow vendor to cancel orders?' => 'დარწმუნებული ხართ, რომ არ აძლევთ გამყიდველს შეკვეთების გაუქმების უფლებას?',
  'After disable the self-registration link will be hidden. You will need to manually add every new vendor from the admin panel.' => 'გამორთვის შემდეგ თვითრეგისტრაციის ბმული დაიმალება. თქვენ მოგიწევთ ხელით დაამატოთ ყველა ახალი გამყიდველი ადმინისტრატორის პანელიდან.',
  'If disabled, vendors will not be able to duplicate products or create new products using the gallery.' => 'თუ გამორთულია, გამყიდველები ვერ შეძლებენ პროდუქტების დუბლირებას ან ახალი პროდუქტების შექმნას გალერეის გამოყენებით.',
  'If you disable this, vendors can not access all products of other available vendors.' => 'თუ ამას გამორთავთ, მოვაჭრეებს არ შეუძლიათ წვდომა სხვა ხელმისაწვდომი მომწოდებლების ყველა პროდუქტზე.',
  'If you enable this, vendors can access all products of other available vendors' => 'თუ ამას ჩართავთ, მოვაჭრეებს შეუძლიათ წვდომა სხვა ხელმისაწვდომი მომწოდებლების ყველა პროდუქტზე',
  'If disabled, vendors can not reply to reviews left for their orders.' => 'თუ გამორთულია, მოვაჭრეებს არ შეუძლიათ უპასუხონ მათ შეკვეთებზე დატოვებულ მიმოხილვებს.',
  'Are you sure to disable Vendor Can Reply Review?' => 'დარწმუნებული ხართ, რომ გამორთავთ გამყიდველს შეუძლია უპასუხოს მიმოხილვას?',
  'Are you sure to enable Vendor Can Reply Review?' => 'დარწმუნებული ხართ, რომ ჩართავთ გამყიდველს შეუძლია უპასუხოს მიმოხილვას?',
  'Are you sure to disable Access All Products?' => 'დარწმუნებული ხართ, რომ გამორთავთ ყველა პროდუქტზე წვდომას?',
  'Are you sure to enable Access All Products?' => 'დარწმუნებული ხართ, რომ ჩართავთ ყველა პროდუქტზე წვდომას?',
  'This allows vendors to duplicate products and create new products using the gallery.' => 'ეს საშუალებას აძლევს მოვაჭრეებს გაამრავლონ პროდუქტები და შექმნან ახალი პროდუქტები გალერეის გამოყენებით.',
  'Are you sure to disable Product Gallery?' => 'დარწმუნებული ხართ, რომ გამორთავთ პროდუქტის გალერეას?',
  'Are you sure to enable Product Gallery?' => 'დარწმუნებული ხართ, რომ ჩართავთ პროდუქტის გალერეას?',
  'This allows new business owners to sign up and apply to sell on your platform by themselves.' => 'ეს საშუალებას აძლევს ახალ ბიზნესის მფლობელებს დარეგისტრირდნენ და განაცხადონ, რომ გაყიდონ თქვენს პლატფორმაზე დამოუკიდებლად.',
  'Are you sure to disable vendor Self Registration?' => 'დარწმუნებული ხართ, რომ გამორთავთ გამყიდველის თვითრეგისტრაციას?',
  'Are you sure to enable vendor Self Registration?' => 'დარწმუნებული ხართ, რომ ჩართავთ გამყიდველის თვითრეგისტრაციას?',
  'Are you sure to allow vendor to cancel orders?' => 'დარწმუნებული ხართ, რომ უფლებას აძლევთ გამყიდველს გააუქმოს შეკვეთები?',
  'Please select at least one option for Update Existing Product' => 'გთხოვთ, აირჩიოთ მინიმუმ ერთი ვარიანტი არსებული პროდუქტის განახლებისთვის',
  'Available Option for Update Existing Product' => 'არსებული პროდუქტის განახლებისთვის ხელმისაწვდომი ვარიანტი',
  'After disable Vendors will not be suspended even if their cash in hand exceeds the set limit.' => 'გათიშვის შემდეგ გამყიდველები არ შეჩერდებიან მაშინაც კი, თუ მათი ნაღდი ფული აღემატება დადგენილ ლიმიტს.',
  'After enable vendor will be automatically suspended when their cash in hand exceeds the allowed limit.' => 'ჩართვის შემდეგ, გამყიდველი ავტომატურად შეჩერდება, როდესაც მისი ნაღდი ფული გადააჭარბებს დაშვებულ ლიმიტს.',
  'Are you sure to disable Cash in Hand Overflow Suspension?' => 'დარწმუნებული ხართ, რომ გამორთავთ Cash in Hand Overflow Suspension?',
  'Are you sure to enable Cash in Hand Overflow Suspension?' => 'დარწმუნებული ხართ, რომ ჩართავთ Cash in Hand Overflow Suspension?',
  'This field is disabled as Cash-in-Hand Overflow suspension is turned OFF' => 'ეს ველი გამორთულია, რადგან ნაღდი ფულის გადაჭარბების შეჩერება გამორთულია',
  'This can not be undone.' => 'ამის გაუქმება შეუძლებელია.',
  'enter_number' => 'შეიყვანეთ ნომერი',
  'Ex:_reference,_Name' => 'მაგ: მითითება, სახელი',
  'Configure limits for cash collected by vendors and suspension rules for exceeding limits.' => 'მოვაჭრეების მიერ შეგროვებული ნაღდი ფულის ლიმიტების კონფიგურაცია და ლიმიტების გადაჭარბების შეჩერების წესები.',
  'Control vendor-related settings such as: Vendor registration availability, Order cancellation permission, Replying to customer reviews, Access to the product gallery, Access to all products. These settings are managed at the vendor level.' => 'აკონტროლეთ გამყიდველთან დაკავშირებული პარამეტრები, როგორიცაა: მომწოდებლის რეგისტრაციის ხელმისაწვდომობა, შეკვეთის გაუქმების ნებართვა, მომხმარებელთა მიმოხილვებზე პასუხის გაცემა, წვდომა პროდუქტის გალერეაზე, წვდომა ყველა პროდუქტზე. ეს პარამეტრები იმართება გამყიდველის დონეზე.',
  'Cash-in-hand control allows the platform to monitor and limit the amount of cash collected by vendors from Cash on Delivery (COD) orders. This feature helps reduce financial risk and ensures timely settlement between the vendor and the platform.' => 'ნაღდი ფულის კონტროლი საშუალებას აძლევს პლატფორმას აკონტროლოს და შეზღუდოს მოვაჭრეების მიერ ნაღდი ფულის შეგროვება ნაღდი ანგარიშსწორებით (COD) შეკვეთებიდან. ეს ფუნქცია ხელს უწყობს ფინანსური რისკის შემცირებას და უზრუნველყოფს დროულ ანგარიშსწორებას გამყიდველსა და პლატფორმას შორის.',
  'This section manages which changes to products by vendors require admin approval before they are applied.' => 'ეს განყოფილება მართავს მომწოდებლების მიერ პროდუქტებში შეტანილ ცვლილებებს, რომლებიც საჭიროებს ადმინისტრატორის დამტკიცებას მათ გამოყენებამდე.',
  'Product Approval' => 'პროდუქტის დამტკიცება',
  'These settings are managed at the vendor level.' => 'ეს პარამეტრები იმართება გამყიდველის დონეზე.',
  'Access to all products' => 'წვდომა ყველა პროდუქტზე',
  'These reasons will be shown to users when they try to cancel an order.' => 'ეს მიზეზები გამოჩნდება მომხმარებლებს, როდესაც ისინი ცდილობენ გააუქმონ შეკვეთა.',
  'business_info' => 'ბიზნეს ინფორმაცია',
  'Mark a default cancellation reason' => 'მონიშნეთ ნაგულისხმევი გაუქმების მიზეზი',
  'Setup your business payment options from here' => 'დააყენეთ თქვენი ბიზნესის გადახდის ვარიანტები აქედან',
  'Access to the product gallery' => 'წვდომა პროდუქტის გალერეაზე',
  'Set a reason as active or inactive' => 'დააყენეთ მიზეზი, როგორც აქტიური ან არააქტიური',
  'Deleting this payment method will permanently remove its data.' => 'გადახდის ამ მეთოდის წაშლა სამუდამოდ წაშლის მის მონაცემებს.',
  'Do you want to delete this payment method?' => 'გსურთ ამ გადახდის მეთოდის წაშლა?',
  'At_least_one_payment_option_must_be_selected' => 'არჩეული უნდა იყოს გადახდის მინიმუმ ერთი ვარიანტი',
  'At least one payment option must be selected' => 'არჩეული უნდა იყოს გადახდის მინიმუმ ერთი ვარიანტი',
  'Referrer' => 'რეფერენტი',
