  'Enabling partial payment will allow customers to pay partially.' => 'ნაწილობრივი გადახდის ჩართვა მომხმარებლებს საშუალებას მისცემს ნაწილობრივ გადაიხადონ.',
  'Combined Payment?' => 'კომბინირებული გადახდა?',
  'Are you sure turn off' => 'დარწმუნებული ხარ რომ გამორთე',
  'Are you sure turn on' => 'დარწმუნებული ხარ რომ ჩართე',
