  'This feature enables customers to partially pay with their wallet balance and complete the payment using other available payment methods.' => 'ეს ფუნქცია მომხმარებელს საშუალებას აძლევს ნაწილობრივ გადაიხადონ საფულის ბალანსით და დაასრულონ გადახდა სხვა ხელმისაწვდომი გადახდის მეთოდების გამოყენებით.',
  'Allow Combined Payment' => 'კომბინირებული გადახდის დაშვება',
  'combined_payment_method_is_required' => 'საჭიროა გადახდის კომბინირებული მეთოდი',
  'Payment Settings Guideline' => 'გადახდის პარამეტრების სახელმძღვანელო',
  'Set the method(s) that customers can pay the remainder after partial payment.' => 'დააყენეთ მეთოდი(ები), რომლითაც მომხმარებელს შეუძლია გადაიხადოს დარჩენილი თანხა ნაწილობრივი გადახდის შემდეგ.',
  'The Partial Payment feature allows customers to split an order payment into two parts. An initial amount is paid using the customer’s wallet balance, and the remaining amount can be paid using Cash on Delivery (COD) or Digital Payment. This feature provides greater payment flexibility and helps customers place orders even when their wallet balance is insufficient for the full amount.' => 'ნაწილობრივი გადახდის ფუნქცია მომხმარებელს აძლევს საშუალებას გაყოს შეკვეთის გადახდა ორ ნაწილად. საწყისი თანხის გადახდა ხდება მომხმარებლის საფულის ბალანსის გამოყენებით, ხოლო დარჩენილი თანხის გადახდა შესაძლებელია ნაღდი ანგარიშსწორებით (COD) ან ციფრული გადახდის გამოყენებით. ეს ფუნქცია უზრუნველყოფს გადახდის უფრო მეტ მოქნილობას და ეხმარება მომხმარებელს შეკვეთების გაკეთებაში მაშინაც კი, როდესაც მათი საფულის ბალანსი არასაკმარისია სრული თანხისთვის.',
