  'Note : Don’t forget to save the information before leaving this page.' => 'შენიშვნა: არ დაგავიწყდეთ ინფორმაციის შენახვა ამ გვერდიდან გასვლამდე.',
  'This will make your app and website live. Customers will be able to browse your services and place orders again.' => 'ეს გახდის თქვენს აპლიკაციას და ვებსაიტს. კლიენტებს შეეძლებათ დაათვალიერონ თქვენი სერვისები და განათავსონ შეკვეთები ხელახლა.',
  'This will temporarily disable the selected systems at the scheduled date and time. You can turn it off anytime after maintenance is complete.' => 'ეს დროებით გამორთავს არჩეულ სისტემებს დაგეგმილ თარიღსა და დროს. თქვენ შეგიძლიათ გამორთოთ ის ნებისმიერ დროს, ტექნიკური სამუშაოების დასრულების შემდეგ.',
  'Are you sure to disable Maintenance Mode?' => 'დარწმუნებული ხართ, რომ გამორთეთ ტექნიკური რეჟიმი?',
