  'Are you sure to turn off maintenance mode?' => 'დარწმუნებული ხართ, რომ გამორთეთ ტექნიკური რეჟიმი?',
  'Are you sure to turn on maintenance mode?' => 'დარწმუნებული ხართ, რომ ჩართოთ ტექნიკური რეჟიმი?',
