  'This is a short statement that shows your company owns the content on your website. It usually includes the copyright symbol (©), the year, and your company name.' => 'ეს არის მოკლე განცხადება, რომელიც აჩვენებს, რომ თქვენი კომპანია ფლობს თქვენს ვებსაიტს. ის ჩვეულებრივ მოიცავს საავტორო უფლებების სიმბოლოს (©), წელს და თქვენი კომპანიის სახელს.',
  'Copyright text' => 'საავტორო ტექსტი',
