  'This option allows users to pick their country code while typing a phone number.' => 'ეს პარამეტრი საშუალებას აძლევს მომხმარებლებს აირჩიონ ქვეყნის კოდი ტელეფონის ნომრის აკრეფისას.',
  'Country Picker' => 'ქვეყნის ამომრჩევი',
  'Use this option to add extra fees to customer orders based on specific, predefined conditions. These charges are added automatically at checkout and are visible to both customers and vendors.' => 'გამოიყენეთ ეს ვარიანტი, რომ დაამატოთ დამატებითი საკომისიო მომხმარებელთა შეკვეთებზე კონკრეტული, წინასწარ განსაზღვრული პირობების საფუძველზე. ეს გადასახადები ავტომატურად ემატება გადახდისას და ხილული იქნება როგორც მომხმარებლებისთვის, ასევე გამყიდველებისთვის.',
  'In the Commission-based model, the platform earns revenue by taking a predefined fixed percentage from each completed order. The commission is automatically deducted from the order value before the remaining amount is settled with the vendor or service provider.' => 'კომისიაზე დაფუძნებულ მოდელში, პლატფორმა იღებს შემოსავალს თითოეული დასრულებული შეკვეთიდან წინასწარ განსაზღვრული ფიქსირებული პროცენტის აღებით. საკომისიო ავტომატურად გამოიქვითება შეკვეთის ღირებულებიდან, სანამ დარჩენილი თანხა გადაირიცხება გამყიდველთან ან სერვისის პროვაიდერთან.',
