  'To use offline payments, you need to set up at least one offline payment method' => 'ხაზგარეშე გადახდების გამოსაყენებლად, თქვენ უნდა დააყენოთ მინიმუმ ერთი ოფლაინ გადახდის მეთოდი',
  'To make available these payment options, you must enable the Offline payment option from' => 'გადახდის ამ ვარიანტების ხელმისაწვდომობისთვის, თქვენ უნდა ჩართოთ ოფლაინ გადახდის ვარიანტი',
  'In this section, you can add offline payment methods to make them available as offline payment options for the customers' => 'ამ განყოფილებაში შეგიძლიათ დაამატოთ ხაზგარეშე გადახდის მეთოდები, რათა ისინი ხელმისაწვდომი გახადოთ როგორც ოფლაინ გადახდის ვარიანტები მომხმარებლებისთვის',
  'The redirect url field is required when landing integration via is url.' => 'გადამისამართების url ველი საჭიროა, როდესაც სადესანტო ინტეგრაცია არის url-ის მეშვეობით.',
  'Choose the integration method for your custom landing page, then provide the required information.' => 'აირჩიეთ ინტეგრაციის მეთოდი თქვენი სადესანტო გვერდისთვის, შემდეგ მიაწოდეთ საჭირო ინფორმაცია.',
  'Provide the URL of the landing page where users will be redirected' => 'მიუთითეთ სადესანტო გვერდის URL, სადაც მომხმარებლები გადამისამართდებიან',
  'please_delete_the_existing_landing_page_first' => 'გთხოვთ, ჯერ წაშალოთ არსებული სადესანტო გვერდი',
  'The file upload must be a file of type: zip.' => 'ფაილის ატვირთვა უნდა იყოს ფაილის ტიპი: zip.',
  'Subscription-based model' => 'გამოწერაზე დაფუძნებული მოდელი',
  'Customers place an order using manual payment methods such as bank transfer or mobile banking. Customers must provide a payment reference or proof. Admin or vendor approval may be required before order confirmation.' => 'მომხმარებლები განათავსებენ შეკვეთას ხელით გადახდის მეთოდების გამოყენებით, როგორიცაა საბანკო გადარიცხვა ან მობილური ბანკინგი. მომხმარებლებმა უნდა წარმოადგინონ გადახდის მითითება ან მტკიცებულება. შეკვეთის დადასტურებამდე შეიძლება საჭირო გახდეს ადმინისტრატორის ან გამყიდველის თანხმობა.',
  'This setting allows the admin to set the amount (in the default currency) that a referring customer will earn. The reward is added to their wallet when someone they refer places and completes their first order on the platform.' => 'ეს პარამეტრი ადმინისტრატორს საშუალებას აძლევს დააყენოს თანხა (ნაგულისხმევი ვალუტით), რომელსაც გამოიმუშავებს მიმართული მომხმარებელი. ჯილდო ემატება მათ საფულეს, როდესაც ვინმეს მიმართავენ ადგილს და დაასრულებენ პირველ შეკვეთას პლატფორმაზე.',
  'Admin can define the minimum order amount for the customer to receive free shipping automatically.' => 'ადმინისტრატორს შეუძლია განსაზღვროს შეკვეთის მინიმალური თანხა, რათა მომხმარებელს ავტომატურად მიიღოს უფასო მიწოდება.',
  'General Setup is the foundational step, where you configure essential business details (time zone, available currency) to set up the business.' => 'ზოგადი დაყენება არის ფუნდამენტური ნაბიჯი, სადაც თქვენ აკონფიგურირებთ არსებით ბიზნეს დეტალებს (საათი ზონა, ხელმისაწვდომი ვალუტა) ბიზნესის დასაყენებლად.',
  'This address is used to locate the business’s physical location.' => 'ეს მისამართი გამოიყენება ბიზნესის ფიზიკური მდებარეობის დასადგენად.',
  'Select your country. This is important for legal, operational, marketing, and payment-related settings.' => 'აირჩიეთ თქვენი ქვეყანა. ეს მნიშვნელოვანია იურიდიული, ოპერატიული, მარკეტინგული და გადახდებთან დაკავშირებული პარამეტრებისთვის.',
  'Free delivery over ($)' => 'უფასო მიწოდება ($)',
  'Customers can’t request a Refund if Admin doesn’t specify a cause for Refund. Admin MUST provide a Refund Reason.' => 'კლიენტები ვერ მოითხოვენ თანხის დაბრუნებას, თუ ადმინისტრატორი არ მიუთითებს თანხის დაბრუნების მიზეზს. ადმინისტრატორმა უნდა მიუთითოს თანხის დაბრუნების მიზეზი.',
  'Users cannot cancel an order if the Admin does not specify a cause for cancellation even though ' => 'მომხმარებლებს არ შეუძლიათ გააუქმონ შეკვეთა, თუ ადმინისტრატორი არ მიუთითებს გაუქმების მიზეზს, მიუხედავად იმისა, რომ ',
  'Write the related refund reasons that customers must select to request a refund. ' => 'დაწერეთ თანხის დაბრუნების შესაბამისი მიზეზები, რომლებიც მომხმარებლებმა უნდა აირჩიონ თანხის დაბრუნების მოთხოვნით. ',
  'Refund Settings Guideline' => 'თანხის დაბრუნების პარამეტრების სახელმძღვანელო',
  'This option enables customers to submit refund requests for their orders. When this option is turned OFF, customers will not be able to request a refund.' => 'ეს ოფცია მომხმარებელს აძლევს საშუალებას წარადგინონ თანხის დაბრუნების მოთხოვნა შეკვეთებზე. როდესაც ეს ვარიანტი გამორთულია, კლიენტები ვერ მოითხოვენ თანხის დაბრუნებას.',
  'This section allows the admin to manage refund cancellation reasons. Admin can create and configure cancellation reasons and control their active status. Customers will see these reasons as options when they request a refund.' => 'ეს განყოფილება საშუალებას აძლევს ადმინისტრატორს მართოს თანხის დაბრუნების გაუქმების მიზეზები. ადმინისტრატორს შეუძლია შექმნას და დააკონფიგურიროს გაუქმების მიზეზები და გააკონტროლოს მათი აქტიური სტატუსი. მომხმარებლები დაინახავენ ამ მიზეზებს, როგორც ვარიანტებს, როდესაც ისინი ითხოვენ თანხის დაბრუნებას.',
  '6ammart supports multiple payment methods to provide flexibility and convenience for customers while ensuring smooth transaction management for the platform and vendors.' => '6ammart მხარს უჭერს გადახდის მრავალ მეთოდს, რათა უზრუნველყოს მომხმარებლებისთვის მოქნილობა და კომფორტი, ხოლო უზრუნველყოს ტრანზაქციის გლუვი მართვა პლატფორმისთვის და მოვაჭრეებისთვის.',
  'Customers pay in cash when they receive their order.' => 'შეკვეთის მიღებისას მომხმარებლები იხდიან ნაღდი ანგარიშსწორებით.',
  'Customers pay online using cards, mobile banking, or digital wallets. Payment is completed before the order is confirmed.' => 'მომხმარებლები იხდიან ონლაინ ბარათების, მობილური ბანკინგის ან ციფრული საფულეების გამოყენებით. გადახდა სრულდება შეკვეთის დადასტურებამდე.',
  'Provide a contact phone number so customers and partners can reach your business easily for urgent inquiries, support needs, or quick questions.' => 'მოგვაწოდეთ საკონტაქტო ტელეფონის ნომერი, რათა მომხმარებლებმა და პარტნიორებმა მარტივად დაუკავშირდნენ თქვენს ბიზნესს გადაუდებელი მოთხოვნების, მხარდაჭერის საჭიროებების ან სწრაფი კითხვებისთვის.',
  'Add your company email address. This email is used for business communication and records.' => 'დაამატეთ თქვენი კომპანიის ელფოსტის მისამართი. ეს ელფოსტა გამოიყენება საქმიანი კომუნიკაციისთვის და ჩანაწერებისთვის.',
  'Enter your official company name. This name represents your business and is used across the system.' => 'შეიყვანეთ თქვენი ოფიციალური კომპანიის სახელი. ეს სახელი წარმოადგენს თქვენს ბიზნესს და გამოიყენება მთელ სისტემაში.',
  'Company Name' => 'კომპანიის სახელი',
  'Customer referral earning settings allow you to specify the wallet balance reward that customers will receive for successfully sharing their unique referral code with new customers who then make a purchase.' => 'მომხმარებელთა რეფერალური შემოსავლის პარამეტრები საშუალებას გაძლევთ მიუთითოთ საფულის ბალანსის ჯილდო, რომელსაც მომხმარებლები მიიღებენ თავიანთი უნიკალური რეფერალური კოდის წარმატებით გაზიარებისთვის ახალ კლიენტებთან, რომლებიც შემდეგ ყიდულობენ.',
  'Define how many loyalty points equal 1 unit of currency(Ex: $1 if the system default currency is dollars). It helps customers understand the value of their points when they want to convert them to wallet money.' => 'განსაზღვრეთ რამდენი ლოიალობის ქულა უდრის 1 ერთეულ ვალუტას (მაგ.: $1, თუ სისტემის ნაგულისხმევი ვალუტა არის დოლარი). ის ეხმარება მომხმარებელს გააცნობიეროს მათი ქულების მნიშვნელობა, როდესაც მათ სურთ მათი გადაქცევა საფულის ფულზე.',
  'Turning on Maintenance mode will temporarily close your online store. Use this when you need to make updates or fix issues.' => 'მოვლის რეჟიმის ჩართვა დროებით დახურავს თქვენს ონლაინ მაღაზიას. გამოიყენეთ ეს, როდესაც გჭირდებათ განახლებების გაკეთება ან პრობლემების მოგვარება.',
  'The smallest amount a customer can add to their wallet at one time.' => 'ყველაზე მცირე თანხა მომხმარებელს შეუძლია დაუმატოს თავის საფულეს ერთდროულად.',
  'Minimum add Amount' => 'დამატების მინიმალური რაოდენობა',
  'Control vendor-related settings such as:' => 'აკონტროლეთ გამყიდველთან დაკავშირებული პარამეტრები, როგორიცაა:',
  'Store Setup Guideline' => 'მაღაზიის დაყენების სახელმძღვანელო',
  'Maintenance mode' => 'მოვლის რეჟიმი',
  'The Admin Notification Setup allows the administrator to configure how system notifications are sent and managed. Admin notifications can be delivered either manually or through Firebase, depending on the selected configuration.' => 'ადმინისტრატორის შეტყობინებების დაყენება საშუალებას აძლევს ადმინისტრატორს დააკონფიგურიროს სისტემის შეტყობინებების გაგზავნა და მართვა. ადმინისტრატორის შეტყობინებების მიწოდება შესაძლებელია ხელით ან Firebase-ის საშუალებით, არჩეული კონფიგურაციის მიხედვით.',
  'It allows customers to place an order to be delivered to their specific address at a selected time. Delivery is handled by a deliveryman or third-party service. It supports real-time order tracking.' => 'ის მომხმარებელს საშუალებას აძლევს განათავსონ შეკვეთა, რათა მიიტანონ მათ კონკრეტულ მისამართზე შერჩეულ დროს. მიწოდებას ახორციელებს მიმწოდებელი ან მესამე მხარის სერვისი. იგი მხარს უჭერს რეალურ დროში შეკვეთის თვალყურის დევნებას.',
  'Scheduled' => 'დაგეგმილი',
  'Business Settings Guideline' => 'ბიზნეს პარამეტრების სახელმძღვანელო',
  'It allows customers to place an order in advance and pick it up directly from the vendor. No delivery charge is applied. The order is prepared for pickup from the vendor.' => 'ეს საშუალებას აძლევს მომხმარებელს წინასწარ განათავსოს შეკვეთა და აიღოს იგი პირდაპირ გამყიდველისგან. მიტანის საფასური არ ვრცელდება. შეკვეთა მზადდება გამყიდველისგან ასაღებად.',
  'It allows customers to place an order and have it delivered to their specified address. Delivery is handled by a deliveryman or third-party service. It supports real-time order tracking.' => 'ის მომხმარებელს საშუალებას აძლევს განათავსონ შეკვეთა და მიაწოდონ იგი მათ მითითებულ მისამართზე. მიწოდებას ახორციელებს მიმწოდებელი ან მესამე მხარის სერვისი. იგი მხარს უჭერს რეალურ დროში შეკვეთის თვალყურის დევნებას.',
  'Automated Request' => 'ავტომატური მოთხოვნა',
  'If_you_enable_this_currency,_you_must_active_at_least_one_digital_payment_method_that_supports_this_currency._Otherwise_customers_cannot_pay_via_digital_payments_from_the_app_and_websites._And_Also_stores_cannot_pay_you_digitally' => 'თუ ჩართავთ ამ ვალუტას, უნდა გააქტიუროთ მინიმუმ ერთი ციფრული გადახდის მეთოდი, რომელიც მხარს უჭერს ამ ვალუტას. წინააღმდეგ შემთხვევაში მომხმარებელს არ შეუძლია გადაიხადოს ციფრული გადახდების საშუალებით აპიდან და ვებსაიტებიდან. და ასევე მაღაზიები ვერ გადაიხდიან ციფრულად',
  'store Details' => 'მაღაზიის დეტალები',
  'store List' => 'მაღაზიის სია',
  'To set different commission for commission based stores.' => 'საკომისიო მაღაზიებისთვის განსხვავებული საკომისიოს დაწესება.',
  'By selecting commission based business model stores can run business with you based on commission based payment per order.' => 'საკომისიოზე დაფუძნებული ბიზნეს მოდელის მაღაზიებს შეუძლიათ აწარმოონ ბიზნესი თქვენთან შეკვეთაზე საკომისიოს საფუძველზე გადახდის საფუძველზე.',
