  'Setup your business model from here' => 'დააყენეთ თქვენი ბიზნეს მოდელი აქედან',
  'Manual Request' => 'ხელით მოთხოვნა',
  'If this option is enabled, customers can add money to their wallet using digital payment methods like bank transfer, mobile wallets, etc.' => 'თუ ეს პარამეტრი ჩართულია, მომხმარებელს შეუძლია ფულის დამატება საფულეში ციფრული გადახდის მეთოდების გამოყენებით, როგორიცაა საბანკო გადარიცხვა, მობილური საფულეები და ა.შ.',
  'This feature allows customers to place orders based on how they want to receive or consume their items.' => 'ეს ფუნქცია საშუალებას აძლევს მომხმარებლებს განათავსონ შეკვეთები იმის მიხედვით, თუ როგორ სურთ მიიღონ ან მოიხმარონ თავიანთი ნივთები.',
