  'Deliveryman referral earning settings allow you to specify the wallet balance reward that the deliveryman will receive for successfully sharing their unique referral code with a new deliveryman for registration.' => 'მიმწოდებლის რეფერალური შემოსავლის პარამეტრები საშუალებას გაძლევთ მიუთითოთ საფულის ბალანსის ჯილდო, რომელსაც მიმწოდებელი მიიღებს თავისი უნიკალური რეფერალური კოდის წარმატებით გაზიარებისთვის ახალ მიმწოდებელთან რეგისტრაციისთვის.',
  'Minimum Point Required to Convert: This setup is for inserting the minimum number of points a deliveryman must have to convert points into a wallet balance.' => 'კონვერტაციისთვის საჭირო მინიმალური ქულა: ეს კონფიგურაცია არის ქულების მინიმალური რაოდენობის ჩასმა, რომელიც მიმწოდებელს უნდა ჰქონდეს ქულების საფულის ბალანსად გადაქცევისთვის.',
  '$1.00 Equivalent to Points: This section is for calculating the wallet value of loyalty points when converting' => '$1.00 ქულების ექვივალენტი: ეს განყოფილება განკუთვნილია ლოიალობის ქულების საფულის ღირებულების გამოსათვლელად კონვერტაციისას',
  'Loyalty Points earn per order: this setup is for setting the value of how much the deliveryman will earn when completing the delivery' => 'ერთგული ქულების დაგროვება თითო შეკვეთაზე: ეს პარამეტრი არის მნიშვნელობის დასაყენებლად, რამდენს გამოიმუშავებს მიმწოდებელი მიწოდების დასრულებისას',
  'You_can_return_only_canceled_parcel_orders' => 'შეგიძლიათ დააბრუნოთ მხოლოდ გაუქმებული ამანათების შეკვეთები',
  'Invalid_return_otp' => 'არასწორი დაბრუნება otp',
